# Best heuristic extracted from training results
# Generated by extract_best_heuristic.py

def score(item, bins):
    valid_bins = bins > item
    scores = np.zeros_like(bins)
    
    if not np.any(valid_bins):
        return scores
    
    # Calculate exponential decay of remaining capacity for valid bins
    exp_capacity = np.exp(-0.1 * (item / bins[valid_bins]))
    
    # Calculate cubic penalty based on the number of items already placed in each bin
    num_items = len(bins) - np.arange(len(bins))
    adjusted_num_items = num_items[valid_bins]
    cubic_penalty = 0.1 * adjusted_num_items**3
    
    # Calculate bonus for bins with item sizes more evenly distributed around the median size of all items in that bin
    if len(bins[valid_bins]) > 0:
        median_item_size = np.median(bins[valid_bins] - item)
        even_distribution_bonus = -np.abs((bins[valid_bins] - item) - median_item_size)**2
    else:
        even_distribution_bonus = 0
    
    # Combine scores: prioritize bins with higher exp capacity, lower cubic penalty, and higher even distribution bonus
    scores[valid_bins] = exp_capacity - cubic_penalty + even_distribution_bonus
    
    return scores
